	SrId    string          // PIC X(4) @0 len=4
	SrSales decimal.Decimal // PIC 9(6)V99 @4 len=8
}

type TierTable struct { // 01 TIER-TABLE, 44 bytes
	TierEntry struct { // group @0 len=11
		TierLimit decimal.Decimal // PIC 9(6)V99 @0 len=8
		TierRate  decimal.Decimal // PIC 9V99 @8 len=3
	}
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsIdx int64 // PIC 9 len=1 = 0
var WsTier int64 // PIC 9 len=1 = 0
var WsComm decimal.Decimal // PIC 9(6)V99 len=8 = 0
var WsTotal decimal.Decimal // PIC 9(9)V99 len=11 = 0
var WsCount int64 // PIC 9(3) len=3 = 0
var WsSalesEd string // PIC ZZZ,ZZ9.99 len=10
var WsRateEd string // PIC 9.99 len=4
var WsCommEd string // PIC ZZZ,ZZ9.99 len=10
var WsTotalEd string // PIC ZZZ,ZZZ,ZZ9.99 len=14

var curRec SalesRec

var tierLimit [5]decimal.Decimal
var tierRate [5]decimal.Decimal

var salesFileLines []string
var salesFilePos int

func isInputDone() bool { return WsEofFlag == "Y" }
func setInputDone()    { WsEofFlag = "Y" }

func pow10(n int) decimal.Decimal {
	return decimal.NewFromInt(1).Shift(int32(n))
}

func fitUnsigned(v decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	totalDigits := intDigits + scale
	mod := pow10(totalDigits)
	scaled := v.Mul(pow10(scale))
	// scaled should already be at scale; truncate toward zero
	scaled = scaled.Truncate(0)
	neg := scaled.IsNegative()
	a := scaled.Abs()
	m := a.Mod(mod)
	if neg {
		m = m.Neg()
	}
	return m.Div(pow10(scale))
}

func formatEdited(pic string, v decimal.Decimal) string {
	// split pic into integer part and fractional part
	dotIdx := strings.Index(pic, ".")
	var intPat, fracPat string
	if dotIdx >= 0 {
		intPat = pic[:dotIdx]
		fracPat = pic[dotIdx+1:]
	} else {
		intPat = pic
		fracPat = ""
	}
	decPlaces := len(fracPat)
	// count integer digit slots (Z and 9)
	intDigits := 0
	for _, c := range intPat {
		if c == 'Z' || c == '9' {
			intDigits++
		}
	}
	rv := v.Round(int32(decPlaces))
	neg := rv.IsNegative()
	abs := rv.Abs()
	scaled := abs.Mul(pow10(decPlaces))
	// scaled is integer
	total := scaled.Round(0).BigInt().Int64() // fits within range for our pictures
	// careful for big totals beyond int64? totals fit (<1e11)
	fracMod := int64(1)
	for i := 0; i < decPlaces; i++ {
		fracMod *= 10
	}
	var intPart int64
	var fracPart int64
	if decPlaces > 0 {
		intPart = total / fracMod
		fracPart = total % fracMod
	} else {
		intPart = total
		fracPart = 0
	}
	// keep low-order digits that fit
	modInt := int64(1)
	for i := 0; i < intDigits; i++ {
		modInt *= 10
	}
	intPart = intPart % modInt
	// zero-padded integer digits
	intStr := fmt.Sprintf("%0*d", intDigits, intPart)
	fracStr := ""
	if decPlaces > 0 {
		fracStr = fmt.Sprintf("%0*d", decPlaces, fracPart)
	}
	// build integer part with suppression
	// map digit index to pattern
	// collect pattern chars for integer part
	type slot struct {
		ch     byte
		digIdx int // -1 for comma
	}
	var slots []slot
	d := 0
	for i := 0; i < len(intPat); i++ {
		c := intPat[i]
		if c == 'Z' || c == '9' {
			slots = append(slots, slot{ch: c, digIdx: d})
			d++
		} else {
			slots = append(slots, slot{ch: c, digIdx: -1})
		}
	}
	// suppression: find last suppressed position? Standard: leading Z zeros -> spaces,
	// commas in suppressed zone -> spaces.
	// Determine for each digit slot whether it is suppressed.
	suppressed := make([]bool, intDigits)
	stillZero := true
	for i := 0; i < intDigits; i++ {
		// find pattern char for this digit
		// locate slot with digIdx==i
		var pc byte
		for _, s := range slots {
			if s.digIdx == i {
				pc = s.ch
				break
			}
		}
		if stillZero && intStr[i] == '0' && pc == 'Z' {
			suppressed[i] = true
		} else {
			// check if this is trailing mandatory? if pc==Z but digit zero but later non-zero?
			// Actually suppression continues only while all previous are zero.
			// If current is zero Z but later digit non-zero, it is still suppressed? No—
			// leading zeros are suppressed even if later non-zero. So logic: suppressed if
			// stillZero and pc==Z and digit==0. Once non-zero encountered, stillZero=false.
			suppressed[i] = false
			if intStr[i] != '0' {
				stillZero = false
			} else {
				// digit zero with pc==9 => not suppressed, but stillZero stays? For comma decision,
				// once we hit a 9 slot, suppression zone ends? Actually a 9 zero prints 0, so
				// subsequent commas are not suppressed. Treat stillZero=false after 9.
				if pc == '9' {
					stillZero = false
				}
			}
		}
		if intStr[i] != '0' {
			stillZero = false
		}
	}
	// Need to recompute correctly: simpler forward pass for output but comma handling needs
	// to know if all digit slots to the left that are not yet printed non-zero are suppressed.
	// Alternative: determine the index of last leading-zero-Z run.
	// Let's compute output for digit slots first, then commas.
	// Actually above loop already sets suppressed for Z zeros at start; but case "001000":
	// i0 '0' Z => suppressed true, stillZero stays true
	// i1 '0' Z => suppressed true
	// i2 '1' Z => suppressed false, stillZero=false
	// i3 '0' Z => suppressed false
	// etc. Good.
	// For "000000": all Z except last 9:
	// i0-4 suppressed true, i5 pc=9 digit 0 => suppressed false. Good.
	var b strings.Builder
	// For comma suppression: comma is space if every digit slot to its left is suppressed
	// (i.e., no non-suppressed digit to the left). Equivalent to: all digit indices < comma's
	// position are suppressed.
	for _, s := range slots {
		if s.digIdx == -1 {
			// comma (or other insertion char)
			// check if any digit to the left is not suppressed
			hasNonSupp := false
			for _, s2 := range slots {
				if s2.digIdx != -1 && s2.digIdx < countDigitsBefore(slots, s) {
					// find position: need order index; simpler: track
					_ = s2
				}
			}
			_ = hasNonSupp
			// Determine left digits: all digIdx corresponding to slots before current slot
			leftHasVisible := false
			for _, s2 := range slots {
				if s2 == s {
					break
				}
				if s2.digIdx != -1 {
					if !suppressed[s2.digIdx] {
						leftHasVisible = true
						break
					}
				}
			}
			if leftHasVisible {
				b.WriteByte(s.ch)
			} else {
				b.WriteByte(' ')
			}
		} else {
			if suppressed[s.digIdx] {
				b.WriteByte(' ')
			} else {
				b.WriteByte(intStr[s.digIdx])
			}
		}
	}
	if dotIdx >= 0 {
		b.WriteByte('.')
		b.WriteString(fracStr)
	}
	out := b.String()
	if neg {
		// replace last leading space with '-' if possible, else overwrite?
		// Not needed for this program (all positive), but handle:
		for i := 0; i < len(out); i++ {
			if out[i] == ' ' {
				// find last space before digits
				continue
			}
		}
		// simple: replace first space from left adjacent to digits? Just prefix minus if room
		bs := []byte(out)
		idx := -1
		for i := len(bs) - 1; i >= 0; i-- {
			if bs[i] == ' ' {
				idx = i
			} else {
				break
			}
		}
		_ = idx
		_ = neg
	}
	return out
}

func countDigitsBefore(slots []struct {
	ch     byte
	digIdx int
}, cur struct {
	ch     byte
	digIdx int
}) int {
	return 0
}

func formatCount(v int64) string {
	m := v % 1000
	if m < 0 {
		m += 1000
	}
	return fmt.Sprintf("%03d", m)
}

func formatTier(v int64) string {
	m := v % 10
	if m < 0 {
		m += 10
	}
	return fmt.Sprintf("%d", m)
}

func MainPara() {
	InitPara()
	// OPEN INPUT SALES-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			salesFileLines = nil
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	} else {
		sc := bufio.NewScanner(f)
		// allow long lines
		sc.Buffer(make([]byte, 1024*1024), 1024*1024)
		for sc.Scan() {
			line := sc.Text()
			// strip possible \r
			if strings.HasSuffix(line, "\r") {
				line = line[:len(line)-1]
			}
			salesFileLines = append(salesFileLines, line)
		}
		f.Close()
	}
	salesFilePos = 0
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	// CLOSE SALES-FILE (nothing)
	SummaryPara()
}

func InitPara() {
	tierLimit[1] = decimal.NewFromFloat(1000.00)
	tierRate[1] = decimal.NewFromFloat(2.50)
	tierLimit[2] = decimal.NewFromFloat(5000.00)
	tierRate[2] = decimal.NewFromFloat(4.00)
	tierLimit[3] = decimal.NewFromFloat(20000.00)
	tierRate[3] = decimal.NewFromFloat(5.50)
	tierLimit[4] = decimal.NewFromFloat(999999.99)
	tierRate[4] = decimal.NewFromFloat(7.25)
	WsEofFlag = "N"
	WsComm = decimal.NewFromInt(0)
	WsTotal = decimal.NewFromInt(0)
	WsCount = 0
	WsIdx = 0
	WsTier = 0
}

func parseRecord(line string) SalesRec {
	// pad with spaces on right to 12
	if len(line) < 12 {
		line = line + strings.Repeat(" ", 12-len(line))
	} else if len(line) > 12 {
		line = line[:12]
	}
	id := line[0:4]
	salesStr := line[4:12]
	// DISPLAY numeric digits only, implied decimal
	// trim spaces
	t := strings.TrimSpace(salesStr)
	var n int64
	if t == "" {
		n = 0
	} else {
		// keep only digits (and sign?)
		filt := ""
		for _, c := range t {
			if c >= '0' && c <= '9' {
				filt += string(c)
			}
		}
		if filt == "" {
			n = 0
		} else {
			var v int64
			fmt.Sscanf(filt, "%d", &v)
			n = v
		}
	}
	d := decimal.New(n, -2)
	// fit to 9(6)V99 low-order
	d = fitUnsigned(d, 6, 2)
	return SalesRec{SrId: id, SrSales: d}
}

func ReadPara() {
	if salesFilePos >= len(salesFileLines) {
		setInputDone()
		return
	}
	line := salesFileLines[salesFilePos]
	salesFilePos++
	curRec = parseRecord(line)
}

func ProcessPara() {
	WsTier = 0
	WsIdx = 1
	for !(WsIdx > 4 || WsTier > 0) {
		if curRec.SrSales.Cmp(tierLimit[WsIdx]) <= 0 {
			WsTier = WsIdx
		}
		WsIdx++
	}
	// COMPUTE WS-COMM ROUNDED = SR-SALES * TIER-RATE(WS-TIER) / 100
	prod := curRec.SrSales.Mul(tierRate[WsTier])
	q := prod.Shift(-2)
	WsComm = q.Round(2)
	WsComm = fitUnsigned(WsComm, 6, 2)
	WsTotal = WsTotal.Add(WsComm)
	WsTotal = fitUnsigned(WsTotal, 9, 2)
	WsCount++
	// keep low-order 3 digits
	WsCount = WsCount % 1000
	WsSalesEd = formatEdited("ZZZ,ZZ9.99", curRec.SrSales)
	WsRateEd = formatEdited("9.99", tierRate[WsTier])
	WsCommEd = formatEdited("ZZZ,ZZ9.99", WsComm)
	fmt.Println(curRec.SrId+" T"+formatTier(WsTier)+" "+WsSalesEd+" "+WsRateEd+"% "+WsCommEd)
	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited("ZZZ,ZZZ,ZZ9.99", WsTotal)
	fmt.Println("REPS: "+formatCount(WsCount)+" TOTAL: "+WsTotalEd)
}

func main() {
	MainPara()
}

